WITH mv AS (SELECT "MATERIAL_ID" AS material_id, "POSTING_DATE" AS posting_date, "MOVEMENT_TYPE" AS movement_type, "QUANTITY" AS quantity FROM public."FACT_MATERIAL_MOVEMENT_PART_001" WHERE "PLANT_ID" = 'HZL_DEMO_01' AND "MOVEMENT_TYPE" IN ('261','262') UNION ALL SELECT "MATERIAL_ID", "POSTING_DATE", "MOVEMENT_TYPE", "QUANTITY" FROM public."FACT_MATERIAL_MOVEMENT_PART_002" WHERE "PLANT_ID" = 'HZL_DEMO_01' AND "MOVEMENT_TYPE" IN ('261','262') UNION ALL SELECT "MATERIAL_ID", "POSTING_DATE", "MOVEMENT_TYPE", "QUANTITY" FROM public."FACT_MATERIAL_MOVEMENT_PART_003" WHERE "PLANT_ID" = 'HZL_DEMO_01' AND "MOVEMENT_TYPE" IN ('261','262')), cons AS (SELECT mv.material_id, date_trunc('month', mv.posting_date)::date AS m, SUM(CASE WHEN mv.movement_type = '261' THEN mv.quantity ELSE -mv.quantity END) AS q FROM mv JOIN public."DIM_MATERIAL" dm ON dm."MATERIAL_ID" = mv.material_id WHERE dm."MATERIAL_TYPE" IN ('ZSPR','ZSPN') AND mv.posting_date >= DATE '2022-01-01' AND mv.posting_date <= DATE '2025-12-31' GROUP BY 1, 2), series AS (SELECT DISTINCT material_id FROM cons), months AS (SELECT generate_series(DATE '2022-01-01', DATE '2025-12-01', INTERVAL '1 month')::date AS m), maint AS (SELECT fr."MATERIAL_ID" AS material_id, to_date(fr."PLANNED_MONTH", 'YYYY-MM') AS m, SUM(fr."REQUIRED_QTY") AS q FROM public."FACT_MAINTENANCE_REQUIREMENT" fr JOIN public."DIM_MAINTENANCE_ORDER" mo ON mo."MAINTENANCE_ORDER_ID" = fr."MAINTENANCE_ORDER_ID" JOIN public."DIM_EQUIPMENT" eq ON eq."EQUIPMENT_ID" = mo."EQUIPMENT_ID" WHERE eq."PLANT_ID" = 'HZL_DEMO_01' GROUP BY 1, 2), shut AS (SELECT fs."MATERIAL_ID" AS material_id, date_trunc('month', se."PLANNED_START_DATE")::date AS m, SUM(fs."REQUIRED_QTY") AS q FROM public."FACT_SHUTDOWN_SCHEDULE" fs JOIN public."DIM_SHUTDOWN_EVENT" se ON se."SHUTDOWN_ID" = fs."SHUTDOWN_ID" WHERE se."PLANT_ID" = 'HZL_DEMO_01' GROUP BY 1, 2), shm AS (SELECT DISTINCT mo2.m FROM months mo2 JOIN public."DIM_SHUTDOWN_EVENT" se ON se."PLANT_ID" = 'HZL_DEMO_01' AND se."PLANNED_START_DATE" < (mo2.m + INTERVAL '1 month') AND se."PLANNED_END_DATE" >= mo2.m), seas AS (SELECT "MATERIAL_GROUP" AS material_group, "CALENDAR_MONTH" AS cm, "SEASON_FACTOR" AS sf FROM public."SEASONALITY_MONTHLY" WHERE "PLANT_ID" = 'HZL_DEMO_01') SELECT s.material_id || '|HZL_DEMO_01' AS series_id, to_char(mo.m, 'YYYY-MM-DD') AS month_start, COALESCE(c.q, 0) AS net_consumption_qty, dmm."MATERIAL_TYPE" AS material_type, COALESCE(ma.q, 0) AS planned_maint_qty, COALESCE(sh.q, 0) AS planned_shutdown_qty, CASE WHEN sm.m IS NULL THEN 0 ELSE 1 END AS plant_shutdown_flag, COALESCE(se2.sf, 1) AS season_index, extract(month from mo.m)::int AS month_of_year FROM series s CROSS JOIN months mo JOIN public."DIM_MATERIAL" dmm ON dmm."MATERIAL_ID" = s.material_id LEFT JOIN cons c ON c.material_id = s.material_id AND c.m = mo.m LEFT JOIN maint ma ON ma.material_id = s.material_id AND ma.m = mo.m LEFT JOIN shut sh ON sh.material_id = s.material_id AND sh.m = mo.m LEFT JOIN shm sm ON sm.m = mo.m LEFT JOIN seas se2 ON se2.material_group = dmm."MATERIAL_GROUP" AND se2.cm = to_char(mo.m, 'YYYY-MM') ORDER BY 1, 2
